func TestValidateAgentUUID(t *testing.T) {
	tests := []struct {
		name    string
		uuid    string
		wantErr bool
		errMsg  string
	}{
		// Valid UUIDs
		{name: "valid uuid lowercase", uuid: "f736da47-b2ca-4f86-bb32-a1bbe582e464", wantErr: false},
		{name: "valid uuid uppercase", uuid: "F736DA47-B2CA-4F86-BB32-A1BBE582E464", wantErr: false},
		{name: "valid uuid mixed case", uuid: "f736DA47-b2ca-4F86-bb32-A1BBE582e464", wantErr: false},
		// Invalid - empty
		{name: "empty uuid", uuid: "", wantErr: true, errMsg: "cannot be empty"},
		// Invalid - wrong format
		{name: "not a uuid", uuid: "not-a-uuid", wantErr: true, errMsg: "invalid agent UUID"},
		{name: "uuid without hyphens", uuid: "f736da47b2ca4f86bb32a1bbe582e464", wantErr: true, errMsg: "invalid agent UUID"},
		{name: "uuid with extra segment", uuid: "f736da47-b2ca-4f86-bb32-a1bbe582e464-extra", wantErr: true, errMsg: "invalid agent UUID"},
		// Security - path traversal attempts
		{name: "path traversal", uuid: "../../../etc/passwd", wantErr: true, errMsg: "invalid agent UUID"},
		{name: "absolute path", uuid: "/etc/passwd", wantErr: true, errMsg: "invalid agent UUID"},
		{name: "windows path", uuid: "C:\\Windows\\System32", wantErr: true, errMsg: "invalid agent UUID"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := ValidateAgentUUID(tt.uuid)
			if tt.wantErr {
				if err == nil {
					t.Errorf("ValidateAgentUUID(%q) expected error containing %q, got nil", tt.uuid, tt.errMsg)
					return
				}
				if !strings.Contains(err.Error(), tt.errMsg) {
					t.Errorf("ValidateAgentUUID(%q) error = %q, want error containing %q", tt.uuid, err.Error(), tt.errMsg)
				}
			} else if err != nil {
				t.Errorf("ValidateAgentUUID(%q) unexpected error: %v", tt.uuid, err)
			}
		})
	}
}

